SELECT P.PRE_NUM, P.TITLE, P.CONTENT, P.CATEGORY, P.REG_DATE, P.VIEW_COUNT, P.USER_ID
FROM TBL_PRETRAINING P
WHERE P.PRE_NUM = #{preNum}

mapper.update:
UPDATE TBL_PRETRAINING
SET TITLE = #{title}, CONTENT = #{content}, CATEGORY = #{category}
WHERE PRE_NUM = #{preNum}

UPDATE TBL_PRETRAINING
SET VIEW_COUNT = VIEW_COUNT + 1
WHERE PRE_NUM = #{preNum}

mapper.select:

SELECT *
FROM (
	SELECT ROWNUM AS RNUM, A.*
	FROM (
		SELECT P.PRE_NUM, P.TITLE, P.CONTENT, P.CATEGORY, P.REG_DATE, P.VIEW_COUNT, P.USER_ID
		FROM TBL_PRETRAINING P
		WHERE P.PRE_NUM > 0





		ORDER BY P.PRE_NUM DESC
	) A
	WHERE ROWNUM <= #{pageEnd}
)
WHERE RNUM >= #{pageStart}
ORDER BY PRE_NUM DESC
